/* HGW sector prototypes. Estimates only; no insurance issuance or transactions. */
'use strict';
(function(root){
  function landed(v){
    const names=['price','inspection','freight','insurance','storage','clearance','delivery','service','dutyRate','vatRate','reference'];
    if(names.some(k=>!Number.isFinite(v[k])||v[k]<0))throw new Error('Non-negative finite inputs required');
    if(v.dutyRate>100||v.vatRate>100)throw new Error('Rate out of range');
    const customsBase=v.price+v.freight+v.insurance;
    const duty=customsBase*v.dutyRate/100;
    const vat=(customsBase+duty)*v.vatRate/100;
    const total=customsBase+duty+vat+v.inspection+v.storage+v.clearance+v.delivery+v.service;
    return {duty,vat,total,saving:v.reference>0?(1-total/v.reference)*100:null};
  }
  function finance(v){
    if(Object.values(v).some(n=>!Number.isFinite(n)||n<0)||v.take>100||v.margin>100||v.allocation>300000000)throw new Error('Invalid assumptions');
    const gmv=v.orders*v.average, revenue=gmv*v.take/100+v.orders*v.fee;
    const contribution=revenue*v.margin/100, operating=contribution-v.fixed;
    return {gmv,revenue,operating,breakeven:v.orders&&contribution?Math.ceil(v.fixed/(contribution/v.orders)):null,remaining:300000000-v.allocation};
  }
  const HGW={landed,finance,qualityMetric};
  if(typeof module!=='undefined'&&module.exports)module.exports=HGW;
  if(!root.document)return;
  let lang='ar'; const T=(ar,en)=>lang==='ar'?ar:en;
  const money=n=>new Intl.NumberFormat(lang==='ar'?'ar-EG':'en-US',{style:'currency',currency:'USD'}).format(n);
  const card=(title,body)=>'<article class="card"><h3>'+title+'</h3><p>'+body+'</p></article>';
  const head=(label,title,body)=>'<div class="eyebrow">'+label+'</div><h1>'+title+'</h1><p class="lede">'+body+'</p>';
  const field=(id,ar,en,value,max)=>'<label class="hgw-field">'+T(ar,en)+'<input type="number" id="'+id+'" min="0" '+(max?'max="'+max+'"':'')+' step="any" value="'+value+'" required></label>';
  HGW.overview=function(l){lang=l;return '<section class="hgw-banner"><div><span class="eyebrow">HGW GLOBAL • CONNECTED SECTORS</span><h2>'+T('حماية أفضل. موارد تدوم. تكلفة أقل.','Better protection. Longer resource life. Lower cost.')+'</h2><p>'+T('هدفنا خفض التكلفة الإجمالية والأسعار بنسبة ٥٠–٨٠٪ مع تحسين الجودة والوفرة وسهولة الوصول والتأمين والضمان. هدف يقاس لكل سوق وفئة، وليس خصمًا مضمونًا.','Our target: 50–80% lower total costs and prices, with better quality, availability, access, insurance and warranty. Measured per market and category; not a guaranteed discount.')+'</p></div><div class="actions"><button class="btn" data-page="insurance">'+T('التأمين والحماية','Insurance')+'</button><button class="btn-outline" data-page="circular">'+T('سوق المستعمل','Circular market')+'</button></div></section>';};
  function insurance(){return head('HGW GLOBAL INSURANCE & RESILIENCE',T('التأمين والحماية وإدارة المخاطر والأزمات','Insurance, protection & crisis resilience'),T('قطاع استراتيجي مستقل يتكامل مع الصحة والطاقة والإسكان والصناعة والتمويل والتكنولوجيا والتجارة الدائرية.','An independent strategic sector connected to health, energy, housing, industry, finance, technology and circular commerce.'))+
    '<div class="cards">'+card('70% — '+T('خدمة السوق الخارجية','External market'),T('هدف لتخصيص الطاقة الخدمية للتعاقدات الخارجية المدفوعة.','Target service capacity for paid external contracts.'))+card('30% — '+T('حماية منظومة HGW','HGW protection'),T('هدف لتخصيص الطاقة لحماية المجموعة وخفض تكلفتها؛ ليست نسبة إيراد مفترضة.','Target service capacity for group protection and cost reduction; not an assumed revenue share.'))+'</div><section class="hgw-banner"><h2>'+T('من التعويض إلى الوقاية والتعافي','From compensation to prevention and recovery')+'</h2><p>'+T('تقييم المخاطر والإنذار المبكر وتقليل احتمالات الخسارة، ثم الحماية والاستجابة والتعويض والتعافي.','Risk assessment and early warning reduce losses; protection, response, claims and recovery follow.')+'</p></section><div class="cards">'+
    card(T('الأفراد والأسر','Individuals & families'),T('الصحة والحياة والدخل والحوادث والممتلكات والمركبات والسفر والمشتريات والشحنات.','Health, life, income, accidents, property, vehicles, travel, purchases and shipments.'))+
    card(T('الشركات والمؤسسات','Companies & institutions'),T('العاملون والأصول والمخزون والمسؤوليات وتعطل الأعمال وسلاسل الإمداد والمخاطر السيبرانية.','People, assets, stock, liability, business interruption, supply chains and cyber risks.'))+
    card(T('الحكومات والجهات العامة','Governments & public bodies'),T('البنية التحتية والمرافق والكوارث والأزمات واستمرارية الخدمات.','Infrastructure, utilities, disasters, crises and continuity of public services.'))+'</div><section class="panel"><h2>'+T('استكشف احتياج الحماية','Explore protection needs')+'</h2><label>'+T('الفئة','Audience')+' <select id="hgw-audience"><option value="individual">'+T('فرد أو أسرة','Individual or family')+'</option><option value="business">'+T('شركة أو مؤسسة','Business or institution')+'</option><option value="government">'+T('جهة حكومية','Public body')+'</option></select></label><div id="hgw-protection" aria-live="polite">'+protection('individual')+'</div><p class="muted">'+T('استكشاف احتياجات فقط؛ لا يصدر وثيقة أو عرض سعر. التغطيات عبر جهات مرخّصة وفق الدولة، بحدود واستثناءات معلنة.','Needs exploration only; no quote or policy is issued. Licensed providers, country rules, limits and exclusions apply.')+'</p></section><div class="cards">'+card(T('حمايتي ووثائقي','My protection & policies'),T('تصميم لوحة للتغطيات والتجديد والتنبيهات؛ الربط الفعلي قيد التطوير.','Planned coverage, renewal and alert dashboard; live integration pending.'))+card(T('المطالبات والطوارئ','Claims & emergencies'),T('المسار المقترح: توثيق الضرر ← تقديم المطالبة ← مراجعة ← قرار ← تعويض وتعافٍ.','Proposed flow: document loss → submit → review → decision → settlement and recovery.'))+'</div>';}
  function protection(a){const copy={individual:T('ابدأ بالصحة والدخل والممتلكات؛ أضف حماية المشتريات والشحن والضمان بحسب احتياجك.','Start with health, income and property; add purchase, shipment and warranty protection as needed.'),business:T('ابدأ بتقييم الأصول والمخزون وتعطل الأعمال؛ ثم المسؤوليات والمخاطر السيبرانية وخطة الاستمرارية.','Start with assets, inventory and interruption; add liability, cyber cover and continuity planning.'),government:T('ابدأ بخريطة مخاطر المرافق والبنية التحتية؛ ثم الطوارئ والكوارث وخطة استمرارية الخدمات والتعافي.','Start with infrastructure and utility risks; add disaster response, service continuity and recovery planning.')};return '<p>'+copy[a]+'</p>';}
  function circular(){return head('HGW GLOBAL CIRCULAR MARKETPLACE',T('إعادة التدوير وسوق المستعمل العالمي','Recycling & global circular marketplace'),T('ربط مباشر بين أصحاب الأصول والمشترين محليًا وعالميًا، مع الفحص والتجديد والضمان والحماية والتوصيل.','Connect asset owners directly with local and global buyers, supported by inspection, refurbishment, warranty, protection and delivery.'))+
    '<div class="cards">'+card(T('كل أصل له فرصة ثانية','A second life for assets'),T('مركبات ومعدات وآلات وإلكترونيات وأثاث ومواد ومنتجات مسموح بتداولها واستيرادها.','Vehicles, machinery, electronics, furniture, materials and other permitted goods.'))+card(T('من السويد إلى مصر','Sweden to Egypt'),T('شراء مباشر من البائع: تحقق من قابلية الاستيراد، افحص الحالة، قارن تكلفة الوصول، ثم اختر الشحن والحماية.','Buy directly: verify import eligibility, inspect condition, compare landed cost, then choose shipping and protection.'))+card(T('الجودة قبل السعر','Quality alongside price'),T('حالة الأصل ومواصفاته ومصدره وتقرير الفحص وشروط الإرجاع والضمان والتأمين تظهر قبل الشراء.','Condition, specifications, origin, inspection, returns, warranty and insurance terms shown before purchase.'))+'</div><section class="panel"><h2>'+T('حاسبة تكلفة الوصول — محاكاة','Landed-cost simulator')+'</h2><p>'+T('أدخل المبالغ بالدولار بعد تحويلها إلى عملة واحدة. مثال توضيحي؛ المعدلات الافتراضية ليست تعرفة رسمية لمصر أو لأي دولة.','Enter all amounts in USD after currency conversion. Illustrative only; default rates are not official tariffs for Egypt or any country.')+'</p><form id="hgw-landed"><div class="hgw-fields">'+field('price','سعر الأصل','Asset price',1000)+field('inspection','الفحص والتجديد','Inspection/refurbishment',50)+field('freight','الشحن والتغليف','Freight/packing',150)+field('insurance','التأمين والضمان','Insurance/warranty',25)+field('storage','التخزين','Storage',20)+field('clearance','خدمة التخليص','Clearance service',40)+field('delivery','التوصيل','Delivery',30)+field('service','رسوم المنصة','Platform service fee',50)+field('dutyRate','الجمارك % — افتراضية','Duty % — hypothetical',10,100)+field('vatRate','الضريبة % — افتراضية','Tax % — hypothetical',14,100)+field('reference','تكلفة البديل المقارن شاملة الخدمات','Comparable all-in reference',3000)+'</div><button class="btn" type="submit">'+T('احسب التكلفة والوفر','Calculate cost & savings')+'</button></form><div id="hgw-landed-result" role="status"></div><p class="muted">'+T('للمحاكاة: وعاء الجمارك = السعر + الشحن + التأمين؛ وعاء الضريبة = الوعاء السابق + الجمارك. القواعد الفعلية تتغير حسب السلعة والمنشأ والوجهة والإعفاءات. إزالة الوسطاء لا تلغي الضرائب أو قيود استيراد المستعمل.','Simulation: duty base = price + freight + insurance; tax base = duty base + duty. Actual rules depend on goods, origin, destination and exemptions. Fewer intermediaries do not remove taxes or used-goods import restrictions.')+'</p></section><section class="panel"><h2>'+T('السادس عشر: النتيجة الاستراتيجية','16. Strategic outcome')+'</h2><p>'+T('بنية تحتية اقتصادية تربط المستهلكين والمنتجين والمخازن والنقل والتأمين والتصنيع وإعادة التدوير؛ تقلل الوساطة غير الضرورية وتحسّن استخدام الموارد والشفافية وتطوّر إيرادات خارجية تخدم بقية القطاعات.','Economic infrastructure linking consumers, producers, warehouses, transport, insurance, manufacturing and recycling; reducing unnecessary intermediaries, improving resource use and transparency, and generating external service revenue.')+'</p><strong>'+T('شبكة عالمية متكاملة تجعل المنتجات والخدمات أكثر كفاءة وعدالة واستدامة.','An integrated global network for more efficient, fair and sustainable access.')+'</strong></section>';}
  function logistics(){return head('HGW LOGISTICS & ECONOMIC MODEL',T('شبكة الخدمات والمحاكاة المالية','Service network & financial simulation'),T('مخازن وبريد ونقل وتخليص جمركي ولوجستيات وتوصيل، بهيكل وحدات مستقلة تحت المجموعة، ومتكاملة مع التأمين والسوق.','Warehousing, post, transport, customs clearance, logistics and delivery: specialist group units integrated with insurance and the marketplace.'))+
    '<div class="cards">'+card('70% — '+T('خدمة الغير','External customers'),T('هدف لتخصيص الطاقة التشغيلية لخدمات مدفوعة للعملاء من خارج المجموعة.','Target share of operational capacity serving paying external customers.'))+card('30% — '+T('خدمة المنظومة','HGW services'),T('هدف لتخصيص الطاقة لخفض تكلفة قطاعات HGW؛ التعاملات الداخلية تُستبعد من الإيرادات المجمّعة.','Target capacity for reducing HGW sector costs; internal transactions eliminated on consolidation.'))+'</div><div class="cards">'+card(T('١. شراكات وأصول محدودة','1. Asset-light partnerships'),T('المنصة الرقمية وشركاء فحص وشحن وتخزين؛ دون شراء أسطول عالمي في البداية.','Digital platform with inspection, shipping and storage partners; no initial global fleet purchase.'))+card(T('٢. مراكز استراتيجية','2. Strategic hubs'),T('مخازن وفحص وتجديد وتجميع شحنات حيث تثبت البيانات الجدوى.','Warehousing, inspection, refurbishment and consolidation where operating data supports investment.'))+card(T('٣. توسع مرتبط بالأداء','3. Performance-led scale'),T('التوسع الدولي وامتلاك أصول إضافية عندما تثبت أفضلية تكلفتها واستغلالها.','International growth and additional owned assets when cost and utilization justify ownership.'))+'</div><section class="panel"><h2>'+T('محاكاة مساهمة القطاع في مشروع ٣٠٠ مليون دولار','Sector simulation within the $300m project')+'</h2><p>'+T('افتراضات تعليمية سنوية قابلة للتعديل؛ لا تفترض تخصيص ميزانية المشروع كلها للقطاع. غيّر القيم لاختبار سيناريو متحفظ أو أساسي أو متفائل في كل مسار.','Editable annual planning assumptions; not the entire project budget allocated to this sector. Adjust values for conservative, base and optimistic scenarios in each path.')+'</p><form id="hgw-finance"><div class="hgw-fields">'+field('orders','المعاملات الخارجية السنوية','External transactions/year',10000)+field('average','متوسط قيمة الأصل','Average asset value',15000)+field('take','عمولة المنصة %','Commission %',4,100)+field('fee','رسوم الخدمات لكل معاملة','Service revenue/transaction',400)+field('margin','هامش المساهمة بعد التكاليف المتغيرة %','Contribution margin after variable costs %',30,100)+field('fixed','المصاريف التشغيلية الثابتة السنوية','Annual fixed operating costs',2000000)+field('allocation','الاستثمار المخصص للقطاع','Sector investment allocation',10000000,300000000)+'</div><button class="btn" type="submit">'+T('احسب السيناريو','Calculate scenario')+'</button></form><div id="hgw-finance-result" role="status"></div><p class="muted">'+T('حجم التداول ليس إيرادًا. بيع أصل بـ١٥٬٠٠٠ دولار ورسوم HGW بـ١٬٠٠٠ دولار يعني إيراد خدمات ١٬٠٠٠ دولار عند عملها كوكيل. هذه محاكاة تشغيلية قبل الإهلاك والتمويل والضريبة، وليست دراسة تدفقات نقدية أو عائد استثمار مكتملة.','GMV is not revenue: a $15,000 asset with $1,000 HGW fees yields $1,000 service revenue when acting as agent. Simulation is before depreciation, financing and tax; not a full cash-flow or investment-return study.')+'</p></section>';}
  function cyber(){return head('HGW CYBERSECURITY, DATA & QUANTUM-SAFE INFRASTRUCTURE',T('أمن المعلومات والبيانات والمرونة الكمية','Information security, data & quantum resilience'),T('قطاع استراتيجي لحماية الأفراد والشركات والمؤسسات والحكومات، متكامل مع التأمين والصحة والتمويل والتجارة واللوجستيات.','A strategic protection sector for individuals, companies, institutions and governments, integrated with insurance, health, finance, commerce and logistics.'))+
    '<section class="panel"><h2>'+T('الخطة المؤسسية الكاملة','Full organizational plan')+'</h2><p>'+T('١٠ أقسام تشغيلية، ١٢ خدمة تجارية، خطة خمس سنوات، حوكمة وتكامل مع قطاعات HGW. مستهدف توافر الخدمات الحرجة ٩٩٫٩٥٪ حسب الفئة وتدقيق أمني مستقل سنوي على الأقل.','10 operating departments, 12 commercial services, a five-year roadmap, governance and cross-sector integration. Critical-service availability target 99.95% by tier; independent security audit at least annually.')+'</p><a href="./cybersecurity-plan.html">'+T('اقرأ الوثيقة التفصيلية بالعربية','Read the detailed plan (Arabic)')+'</a></section><section class="hgw-banner"><h2>'+T('حماية أعلى، خدمة أسهل، تكلفة أقل','Stronger protection, easier access, lower cost')+'</h2><p>'+T('هدف خفض التكلفة الإجمالية للخدمات المماثلة بنسبة ٥٠–٨٠٪ عبر الخدمات المشتركة والأتمتة والوقاية، مع قياس الجودة والتوافر وسرعة الاستجابة؛ ليس ضمانًا لنسبة وفر أو منع كل اختراق.','Target 50–80% lower total cost for comparable services through shared services, automation and prevention, with measured quality, availability and response; not a guaranteed saving or prevention of every breach.')+'</p></section><div class="cards">'+
    card('70% — '+T('خدمة الغير','External services'),T('طاقة تشغيلية مستهدفة لخدمات أمن مدفوعة للأفراد والمنشآت والجهات العامة خارج المجموعة.','Target capacity for paid security services to external individuals, businesses and public bodies.'))+
    card('30% — '+T('حماية HGW','Protecting HGW'),T('طاقة لحماية قطاعات المجموعة وخفض تكلفتها؛ فصل الإيرادات الخارجية عن الوفورات الداخلية واستبعاد التعاملات الداخلية عند التجميع.','Capacity to protect HGW sectors and reduce costs; external revenue separated from internal savings and internal transactions eliminated on consolidation.'))+'</div><div class="cards">'+
    card(T('الهوية والوصول','Identity & access'),T('مصادقة متعددة العوامل، أقل صلاحية لازمة، إدارة حسابات العاملين والعملاء والأسرار والمفاتيح.','Multi-factor authentication, least privilege, workforce and customer access, secrets and key management.'))+
    card(T('حماية البيانات والخصوصية','Data protection & privacy'),T('تشفير أثناء النقل والتخزين، تصنيف البيانات، تقليل جمعها، إدارة الموافقات والاحتفاظ والحذف والنسخ الاحتياطي واختبار الاستعادة.','Encryption in transit and at rest, classification, collection minimization, consent, retention, deletion, backups and restore testing.'))+
    card(T('المراقبة والاستجابة والتعافي','Monitoring, response & recovery'),T('مركز عمليات أمنية مُدار، كشف التهديدات والثغرات، اختبارات مصرح بها، استجابة للحوادث وخطط تعافٍ مرتبطة بالتأمين السيبراني.','Managed security operations, threat and vulnerability detection, authorized testing, incident response and recovery linked to cyber insurance.'))+
    card(T('تشفير مقاوم للحوسبة الكمية','Post-quantum cryptography'),T('حصر الخوارزميات والبيانات طويلة الحساسية، ثم انتقال تدريجي قابل للاختبار إلى معايير مثل ML-KEM وML-DSA وSLH-DSA، مع مرونة تبديل الخوارزميات وإدارة المفاتيح.','Inventory algorithms and long-lived sensitive data; plan tested migration to standards such as ML-KEM, ML-DSA and SLH-DSA, with crypto agility and key management.'))+
    card(T('التوزيع الكمي للمفاتيح — مسار متخصص','Quantum key distribution — specialist track'),T('خيار بحثي وتعاقدي للوصلات المناسبة يتطلب أجهزة وقنوات وشركاء متخصصين. ليس ميزة تعمل بمجرد تثبيت التطبيق، ولا بديلًا عن أمن الأجهزة والهوية.','A specialist research and procurement option for suitable links requiring dedicated devices, channels and partners. Not activated by installing an app; endpoint and identity security remain necessary.'))+
    card(T('جودة وتوافر وضمان تعاقدي','Quality, availability & contractual assurance'),T('مستويات خدمة معلنة حسب الباقة: التوافر وزمن الكشف والاستجابة والاستعادة ونجاح النسخ الاحتياطي؛ حدود المسؤولية والتغطية التأمينية واضحة.','Plan-specific SLAs for availability, detection, response, recovery and backup success, with clear liability and insurance coverage limits.'))+'</div><section class="panel"><h2>'+T('مسار التنفيذ','Delivery path')+'</h2><p>'+T('تقييم وموافقة النطاق ← حصر الأصول والمخاطر ← تصميم الحماية والتكلفة ← تطبيق واختبار ← مراقبة وتحسين وتعافٍ.','Scope authorization and assessment → asset/risk inventory → protection and cost design → implementation and testing → monitoring, improvement and recovery.')+'</p><p class="muted">'+T('هذه واجهة تعريفية بالخدمات المقترحة. لم يُفعَّل مركز عمليات أو تشفير كمي أو حماية إنتاجية بمجرد إضافة هذا القسم؛ البيانات الحالية محلية وتجريبية.','This describes proposed services. Adding this section does not activate a security operations center, quantum encryption or production protection; current data is local demonstration data.')+'</p></section>';}
  function research(){return head('HGW GLOBAL RESEARCH, INNOVATION & KNOWLEDGE',T('الدراسات والبحث العلمي والملكية الفكرية','Studies, scientific research & intellectual property'),T('منظومة متكاملة للمراكز المتخصصة والبيانات وبراءات الاختراع والخوارزميات والمعارف والخبرات؛ تربط البحث بالتطبيق والإنتاج وخدمة الإنسان.','An integrated network of specialist centers, data, patents, algorithms, knowledge and expertise connecting research with practical applications, production and human welfare.'))+
    '<section class="hgw-banner"><h2>'+T('من السؤال العلمي إلى أثر قابل للقياس','From scientific questions to measurable impact')+'</h2><p>'+T('دراسات موثقة وأبحاث قابلة للتحقق، ثم تجارب ونماذج أولية ونقل تقنية وترخيص؛ لدعم الجودة والوفرة وخفض التكلفة الكلية المستهدف ٥٠–٨٠٪ حيث تثبت المقارنة الجدوى.','Documented studies and verifiable research, followed by experiments, prototypes, technology transfer and licensing, supporting quality, availability and a targeted 50–80% reduction in total cost where comparable evidence supports it.')+'</p></section><div class="cards">'+
    card('70% — '+T('خدمات وبحوث للسوق الخارجية','External research & services'),T('نموذج مستهدف للطاقة الخدمية: دراسات وأبحاث تعاقدية واختبارات وترخيص واستشارات وتدريب للأفراد والمؤسسات والحكومات.','Target service capacity for commissioned studies, research, testing, licensing, consulting and training for external individuals, institutions and governments.'))+
    card('30% — '+T('ابتكار لمنظومة HGW','Innovation for HGW'),T('طاقة لدعم قطاعات HGW وتطوير منتجاتها وخفض تكلفتها. تُقاس الطاقة الفعلية وتُفصل الوفورات الداخلية عن الإيرادات الخارجية.','Capacity supporting HGW sectors, product development and cost reduction. Actual capacity is measured; internal savings are separated from external revenue.'))+'</div><div class="cards">'+
    card(T('مراكز البحث العلمي المتخصصة','Specialist scientific centers'),T('الصحة والدواء؛ الطاقة والمياه والمناخ؛ الزراعة والغذاء؛ المواد والصناعة وإعادة التدوير؛ النقل والإسكان؛ الحوسبة والذكاء الاصطناعي والأمن والتشفير؛ الاقتصاد والسياسات والعلوم الاجتماعية.','Health and medicine; energy, water and climate; agriculture and food; materials, industry and recycling; transport and housing; computing, AI, cybersecurity and cryptography; economics, policy and social sciences.'))+
    card(T('الدراسات والجدوى وقياس الأثر','Studies, feasibility & impact'),T('دراسات علمية وفنية واقتصادية وسوقية واجتماعية وبيئية، ومراجعات أدلة وتقييم مستقل للفرضيات والتكلفة والعائد.','Scientific, technical, economic, market, social and environmental studies, evidence reviews and independent assessment of assumptions, costs and benefits.'))+
    card(T('منظومة البيانات والأدلة','Data & evidence infrastructure'),T('فهرسة المصادر والمنهجيات والجودة والإصدارات والصلاحيات والتراخيص، مع تقليل البيانات الشخصية وحماية البيانات الحساسة.','Catalog sources, methods, quality, versions, access rights and licenses, minimizing personal data and protecting sensitive datasets.'))+
    card(T('براءات الاختراع والملكية الفكرية','Patents & intellectual property'),T('إفصاح اختراع سري، بحث أولي في السوابق، مراجعة الملكية وقابلية الحماية، إيداع عند اعتماده، ثم متابعة الحقوق والتجديد والترخيص.','Confidential invention disclosure, preliminary prior-art research, ownership and protectability review, approved filing, then rights, renewal and licensing management.'))+
    card(T('الخوارزميات والبرمجيات والنماذج','Algorithms, software & models'),T('مستودعات بإصدارات موثقة وتراخيص واختبارات ومقاييس أداء وإعادة إنتاج النتائج؛ مراجعة حقوق الشيفرات والبيانات والنماذج التابعة للغير.','Versioned repositories, licenses, tests, benchmarks and reproducible results; review third-party code, data and model rights.'))+
    card(T('المعارف والخبرات وشبكة الخبراء','Knowledge, expertise & experts'),T('مكتبة معرفية ودروس مستفادة وأدلة عمل، وشبكة خبراء بمهارات ومؤهلات يجري التحقق منها ومراجعة الأقران وتوثيق المساهمات.','Knowledge library, lessons learned and playbooks, plus an expert network with verified credentials, peer review and contribution records.'))+
    card(T('نقل التقنية وتسويق الابتكار','Technology transfer & commercialization'),T('ترخيص تقنيات وخوارزميات وبيانات مرخّصة، بحث تعاقدي، شراكات جامعية، حاضنات ونماذج أولية وتدريب؛ وفق اتفاقيات الحقوق وتقاسم العائد.','Technology, algorithm and authorized-data licensing, commissioned research, university partnerships, incubation, prototypes and training under clear rights and revenue-sharing agreements.'))+
    card(T('الجودة والأخلاقيات والحوكمة','Quality, ethics & governance'),T('مراجعة علمية مستقلة وتعارض المصالح وموافقات البحث عند اللزوم، وحفظ حقوق الباحثين والممولين والمشاركين والمعارف المجتمعية.','Independent scientific review, conflicts of interest, required research approvals, and protection of researcher, funder, participant and community knowledge rights.'))+'</div><section class="panel"><h2>'+T('دورة البحث والابتكار','Research & innovation lifecycle')+'</h2><p>'+T('احتياج أو سؤال ← مراجعة الأدلة والحقوق ← خطة ومنهجية وميزانية وموافقات ← بحث وتجربة ← مراجعة وتحقق ← قرار حماية أو نشر ← تطبيق أو ترخيص ← قياس الأثر والتحسين.','Need or question → evidence and rights review → methods, budget and approvals → research and experiments → review and validation → protection or publication decision → deployment or licensing → impact measurement and improvement.')+'</p></section><section class="panel"><h2>'+T('فهرس المعرفة — أمثلة تصميمية','Knowledge catalog — illustrative examples')+'</h2><p>'+T('اختر نوع الأصل المعرفي لاستعراض بياناته المقترحة. لا توجد أبحاث منشورة أو براءات مسجلة مثبتة بهذه الأمثلة.','Choose an asset type to explore proposed metadata. These examples do not evidence published research or registered patents.')+'</p><label>'+T('نوع الأصل','Asset type')+' <select id="hgw-knowledge-type"><option value="study">'+T('دراسة علمية','Scientific study')+'</option><option value="data">'+T('مجموعة بيانات','Dataset')+'</option><option value="patent">'+T('اختراع وملكية فكرية','Invention & IP')+'</option><option value="algorithm">'+T('خوارزمية','Algorithm')+'</option><option value="expert">'+T('معرفة وخبرة','Knowledge & expertise')+'</option></select></label><div id="hgw-knowledge-record" aria-live="polite">'+knowledgeRecord('study')+'</div></section><section class="panel"><h2>'+T('التكامل ومؤشرات الأداء','Integration & performance indicators')+'</h2><p>'+T('تطوير نماذج المخاطر للتأمين، وفحص وتجديد الأصول للسوق الدائري، وتحسين النقل والمخازن، واختبار أمن البيانات والتشفير، ودعم الصحة والطاقة والتعليم والصناعة.','Risk models for insurance, asset inspection and refurbishment for circular commerce, logistics optimization, data-security and cryptography testing, and support for health, energy, education and industry.')+'</p><p>'+T('تقاس الجودة بقابلية إعادة الإنتاج والمراجعة المستقلة، والأثر بتطبيق النتائج والوفر الصافي والإيرادات الخارجية المرخّصة، مع متابعة زمن نقل التقنية ونسبة ٧٠/٣٠. عدد البراءات وحده لا يثبت القيمة.','Measure quality through reproducibility and independent review; impact through adoption, net savings and external licensing revenue, alongside transfer time and the 70/30 capacity split. Patent count alone does not establish value.')+'</p><a href="./research-proposal.html">'+T('المقترح التفصيلي للمراكز العشرة والسوق المعرفية','Full ten-center and knowledge-market proposal (Arabic)')+'</a><br><a href="./research-plan.html">'+T('اقرأ الخطة التفصيلية','Read the detailed plan (Arabic)')+'</a><p class="muted">'+T('القسم واجهة وخطة تنفيذية مقترحة؛ لم تُنشأ مختبرات أو شراكات أو تُسجل براءات بمجرد إضافته.','This section is a proposed interface and delivery plan; adding it does not establish labs, partnerships or registered patents.')+'</p></section>';}
  function knowledgeRecord(kind){const entries={
    study:[T('دراسة جدوى تجديد أصل مستعمل','Used-asset refurbishment feasibility'),T('سؤال البحث، المنهجية، الافتراضات، المصادر، فريق البحث، المراجعة، الإصدار وحدود النتائج.','Research question, methods, assumptions, sources, team, review, version and limitations.')],
    data:[T('بيانات دورة حياة المنتجات','Product lifecycle data'),T('المنشأ والموافقة أو الأساس القانوني، مخطط الحقول، الجودة، الترخيص، مدة الاحتفاظ وصلاحيات الوصول.','Provenance, consent or lawful basis, schema, quality, license, retention and access permissions.')],
    patent:[T('فكرة تقنية قيد التقييم','Technical idea under evaluation'),T('المخترعون والمالكون، مستوى السرية، السوابق، حالة الطلب والبلدان والمواعيد واتفاقيات الترخيص. المثال ليس براءة مسجلة.','Inventors, owners, confidentiality, prior art, application status, jurisdictions, deadlines and license agreements. This example is not a registered patent.')],
    algorithm:[T('تحسين تجميع الشحنات','Shipment consolidation optimization'),T('النسخة، مصدر الشيفرة، حقوق الاستخدام، بيانات الاختبار، المقاييس، قابلية التكرار والتحيزات والقيود.','Version, code provenance, usage rights, evaluation data, metrics, reproducibility, biases and limitations.')],
    expert:[T('خبرة فحص وتجديد المعدات','Equipment inspection & refurbishment expertise'),T('التخصص والمؤهلات والتحقق، المساهمات، مراجعة الخبراء، الموافقات وحدود إتاحة الخبرة وترخيصها.','Specialty, qualifications and verification, contributions, peer review, consent, sharing scope and licensing.')]
  };const item=entries[kind]||entries.study;return '<h3>'+item[0]+'</h3><p>'+item[1]+'</p><small>'+T('سجل توضيحي فقط — لا تُدخل معلومات سرية في النموذج التجريبي.','Illustrative record only — do not enter confidential information in this prototype.')+'</small>';}
  function quality(){return head('HGW GLOBAL QUALITY, SAFETY & DIGITAL TWINS',T('الجودة والسلامة والأمان والتدريب والمحاكاة','Quality, safety, security, training & simulation'),T('منظومة أفقية مستقلة تخدم جميع قطاعات HGW: تحدد المتطلبات، تدرب الكفاءات، تقيس الأداء، تختبر السيناريوهات وتتابع التحسين المستمر.','An independent cross-sector ecosystem defining requirements, building competence, measuring performance, testing scenarios and driving continuous improvement across HGW.'))+
    '<section class="panel"><h2>'+T('الهيكل المتكامل: عشرة مراكز','Integrated structure: ten centers')+'</h2><ol>'+[
T('الجودة والمعايير','Quality & standards'),T('السلامة والصحة المهنية','Safety & occupational health'),T('الأمان وإدارة المخاطر','Security & risk management'),T('أكاديمية التدريب والتأهيل','Training & competency academy'),T('القياس والمعايرة والاختبارات','Metrology, calibration & testing'),T('المحاكاة المتقدمة','Advanced simulation'),T('التوأمة الرقمية','Digital twins'),T('التفتيش والتدقيق والمطابقة','Inspection, audit & conformity'),T('الذكاء الاصطناعي والتحليلات التنبؤية','AI & predictive analytics'),T('البحث والتطوير والابتكار في الجودة','Quality research, development & innovation')].map(x=>'<li>'+x+'</li>').join('')+'</ol><p>'+T('التدقيق المستقل منفصل عن التصميم والاستشارات، مع شراكات مختبرية واعتماد ضمن الصلاحيات الفعلية.','Independent audit is separated from design and consulting, with laboratory partnerships and accreditation within actual authorization.')+'</p><a href="./quality-proposal.html">'+T('المقترح الكامل: المراكز والخدمات والمعايير ومراحل التنفيذ','Full proposal: centers, services, standards & implementation (Arabic)')+'</a></section><section class="panel"><h2>HGW Quality Intelligence Platform</h2><label>'+T('استكشف اللوحات المقترحة','Explore proposed dashboards')+' <select id="hgw-quality-dashboard">'+[
['quality',T('الجودة','Quality')],['safety',T('السلامة','Safety')],['training',T('التدريب','Training')],['simulation',T('المحاكاة','Simulation')],['twins',T('التوأمة الرقمية','Digital twins')],['audit',T('التدقيق','Audit')],['research',T('البحث والتطوير','R&D')],['finance',T('الإدارة المالية','Finance')]].map(([id,label])=>'<option value="'+id+'">'+label+'</option>').join('')+'</select></label><div id="hgw-quality-dashboard-content" aria-live="polite">'+qualityDashboard('quality')+'</div><p class="muted">'+T('معاينة لمتطلبات اللوحات، وليست مؤشرات فعلية أو أنظمة متصلة.','Preview of dashboard requirements, not actual metrics or connected systems.')+'</p></section><section class="hgw-banner"><h2>'+T('جودة قابلة للقياس قبل التنفيذ وبعده','Measurable quality before and after deployment')+'</h2><p>'+T('رفع الجودة والوفرة والسلامة وسهولة الخدمة، وخفض تكلفة العيوب والهدر والحوادث. يسهم القطاع في هدف خفض التكلفة الإجمالية ٥٠–٨٠٪ عندما تثبت المقارنة المتكافئة ذلك، دون خفض متطلبات الأمان.','Improve quality, availability, safety and ease of service while reducing defects, waste and incident costs. Contribute to the 50–80% total-cost reduction target where equivalent comparisons support it, while preserving safety requirements.')+'</p></section><div class="cards">'+
    card('70% — '+T('خدمات خارجية','External services'),T('طاقة خدمية مستهدفة للتدريب والقياس والاختبارات والمحاكاة والتوأمة الرقمية والتدقيق للعملاء الخارجيين.','Target capacity for external training, measurement, testing, simulation, digital twins and audits.'))+
    card('30% — '+T('جودة قطاعات HGW','HGW sector quality'),T('طاقة لتحسين خدمات المجموعة ومنتجاتها وخفض تكلفة الإخفاق؛ تخصيص تكلفة شفاف وفصل الوفر الداخلي عن الإيراد الخارجي.','Capacity improving group products and services and reducing failure costs, with transparent cost allocation and separation of internal savings from external revenue.'))+'</div><div class="cards">'+
    card(T('أكاديمية الجودة والسلامة','Quality & safety academy'),T('تقييم فجوات المهارات، تدريب حسب الدور والمخاطر، تمارين طوارئ ومحاكاة، اختبار نظري وعملي، إعادة تأهيل ومتابعة صلاحية الكفاءة.','Skill-gap assessment, role- and risk-based learning, emergency drills and simulation, theory and practical assessments, refresher training and competence renewal.'))+
    card(T('المعايير والمطابقة','Standards & conformity'),T('سجل للمتطلبات القانونية ومعايير القطاع وإصداراتها، وأدلة المطابقة وخطط التدقيق؛ أمثلة مرجعية ISO 9001 وISO 45001 وISO/IEC 27001 وISO/IEC 17025 بحسب النطاق.','Register applicable legal and sector requirements, editions, evidence and audit plans; reference examples include ISO 9001, ISO 45001, ISO/IEC 27001 and ISO/IEC 17025 according to scope.'))+
    card(T('القياس والاختبارات والمعايرة','Measurement, testing & calibration'),T('خط أساس وحدود قبول ووحدات قياس ومعايرة وتتبع وعدم يقين، وفحص الموردين والمنتجات والعمليات قبل التسليم وبعده.','Baselines, acceptance limits, units, calibration, traceability and measurement uncertainty; inspect suppliers, products and processes before and after delivery.'))+
    card(T('السلامة والأمان وإدارة المخاطر','Safety, security & risk'),T('سلامة مهنية ومنتجات وعمليات، أمن مادي ورقمي بالتكامل مع قطاع الأمن، تحليل مخاطر وحوادث وشبه حوادث وإجراءات وقائية واستجابة للطوارئ.','Occupational, product and process safety, physical and digital security integrated with cybersecurity, risk analysis, incidents, near misses, prevention and emergency response.'))+
    card(T('المحاكاة واختبار السيناريوهات','Simulation & scenario testing'),T('اختبار الأحمال والأعطال والإخلاء والنقل والإنتاج قبل التنفيذ، مع توثيق الفرضيات وحدود النموذج والتحقق من النتائج وتحليل الحساسية.','Test loads, failures, evacuation, transport and production before deployment; document assumptions, model limitations, validation and sensitivity analysis.'))+
    card(T('التوأمة الرقمية','Digital twins'),T('نماذج لأصول ومنشآت وعمليات مرتبطة ببيانات مصرح بها عند توافر التكامل؛ متابعة الحالة والصيانة والتنبؤ والاختبار، مع توثيق دقة البيانات ومعدل التحديث.','Models of assets, facilities and processes linked to authorized data when integration exists; condition monitoring, maintenance, prediction and testing, with documented data accuracy and update rates.'))+
    card(T('التدقيق والتحسين المستمر','Audit & continuous improvement'),T('تسجيل عدم المطابقة وتحليل السبب الجذري والإجراء التصحيحي والوقائي، وتعيين مسؤول وموعد والتحقق من الفاعلية قبل الإغلاق.','Record nonconformities, root causes and corrective/preventive actions, with an owner, deadline and effectiveness verification before closure.'))+
    card(T('الضمان والشفافية','Assurance & transparency'),T('ربط تقارير الفحص والضمان والتأمين ونتائج التدريب بالأصل والخدمة؛ الفصل بين الفحص الداخلي وشهادة المطابقة الصادرة من جهة مخولة.','Link inspection, warranty, insurance and training evidence to assets and services; distinguish internal inspection from certificates issued by authorized bodies.'))+'</div><section class="panel"><h2>'+T('محاكاة تعليمية لمؤشر الجودة','Illustrative quality-metric simulation')+'</h2><p>'+T('أدخل حجم فحص وعدد وحدات معيبة في سيناريو افتراضي. الحساب لا يتصل بحساسات ولا يصدر شهادة مطابقة.','Enter inspected units and defective units for a hypothetical scenario. This calculation has no sensor connection and issues no conformity certificate.')+'</p><form id="hgw-quality"><div class="hgw-fields">'+field('inspected','الوحدات المفحوصة','Inspected units',1000)+field('defective','الوحدات المعيبة','Defective units',20)+field('target','الحد الأعلى المستهدف للعيوب %','Maximum target defect rate %',1,100)+'</div><button class="btn" type="submit">'+T('احسب وقارن بالهدف','Calculate & compare')+'</button></form><div id="hgw-quality-result" role="status"></div></section><section class="panel"><h2>'+T('توأم رقمي استراتيجي مترابط لمنظومة HGW','An interconnected strategic HGW digital twin')+'</h2><p>'+T('ربط نماذج المصانع والطاقة والمستشفيات والأسواق والنقل واللوجستيات والتأمين والتمويل والبحث بدراسات الجدوى والميزانيات والجداول الزمنية. تقارن سيناريوهات مثل ٥ مصانع و٥٠ مصنعًا باستخدام افتراضات معلنة للطاقة والموارد والتكاليف والإيرادات والمخاطر، مع مراعاة القيود وعدم افتراض التوسع الخطي.','Link factories, energy, hospitals, marketplaces, transport, logistics, insurance, finance and research models with feasibility studies, budgets and schedules. Compare scenarios such as 5 versus 50 factories using explicit energy, resource, cost, revenue and risk assumptions, respecting constraints rather than assuming linear scaling.')+'</p><p>'+T('تُحدَّث التوقعات عند وصول بيانات فعلية متحقَّق منها، مع سجل مصادر وإصدارات وعدم يقين ومراجعة بشرية. هذا تصميم مستهدف؛ لم يُبنَ توأم حي أو نموذج اقتصادي مترابط في هذه النسخة، والمحاكاة لا تضمن نجاح الاستثمار.','Update forecasts when verified operational data arrives, preserving provenance, versions, uncertainty and human review. This is a target design; no live twin or integrated economic model has been built in this version, and simulations do not guarantee investment success.')+'</p></section><section class="panel"><h2>'+T('دورة العمل والتكامل','Workflow & integration')+'</h2><p>'+T('متطلبات ومخاطر ← خط أساس ← تدريب ونموذج محاكاة ← اختبار وقياس ← مراجعة بشرية وقبول ← مراقبة وتحسين. المراكز البحثية تطور المنهجيات والنماذج؛ قطاع الجودة يتحقق من المطابقة والأداء باستقلالية.','Requirements and risks → baseline → training and simulation model → testing and measurement → human review and acceptance → monitoring and improvement. Research centers develop methods and models; quality independently verifies conformity and performance.')+'</p><a href="./quality-plan.html">'+T('الخطة التفصيلية للجودة والسلامة والتوأمة الرقمية','Detailed quality, safety and digital twin plan (Arabic)')+'</a><p class="muted">'+T('الواجهة تجريبية؛ لا اعتماد أو شهادة ISO أو توأم حي أو ضمان سلامة مثبت بمجرد إضافة القسم.','Prototype interface; adding this section does not establish accreditation, ISO certification, a live twin or verified safety assurance.')+'</p></section>';}
  function qualityDashboard(kind){const descriptions={
quality:T('مؤشرات المطابقة والعيوب والمرتجعات ورضا المستفيدين وتكلفة الإخفاق والإجراءات التصحيحية.','Conformity, defects, returns, customer satisfaction, failure costs and corrective actions.'),
safety:T('المخاطر والحوادث وشبه الحوادث والتنبيهات وخطط الطوارئ؛ مع تعريف التعرض وفترة القياس.','Risks, incidents, near misses, alerts and emergency plans, with exposure and measurement periods defined.'),
training:T('البرامج والمتدربون ونتائج الاختبارات والكفاءة والشهادات ومواعيد التجديد؛ تدريب حضوري ورقمي ومحاكاة وواقع افتراضي ومعزز حسب الجدوى.','Programs, learners, assessments, competence, certificates and renewal dates; in-person, digital, simulated and VR/AR learning where feasible.'),
simulation:T('السيناريوهات والافتراضات والإصدارات والنتائج وتحليل الحساسية ودقة التنبؤ مقارنة بالأداء الحقيقي.','Scenarios, assumptions, versions, results, sensitivity and prediction accuracy against actual performance.'),
twins:T('الأصول وحالتها وجودة البيانات وحداثتها ودقة النماذج والأعطال والصيانة؛ لا ادعاء اتصال لحظي دون تكامل فعلي.','Assets, condition, data quality and freshness, model accuracy, faults and maintenance; no real-time claim without actual integration.'),
audit:T('نطاق التدقيق واستقلال المدقق والأدلة وعدم المطابقة والتوصيات والمسؤوليات والمواعيد والتحقق من الإغلاق.','Scope, auditor independence, evidence, nonconformities, recommendations, owners, deadlines and closure verification.'),
research:T('احتياجات التشغيل والابتكارات والنماذج الأولية والخوارزميات والبراءات ونتائج التحقق بالتكامل مع قطاع البحث.','Operating needs, innovations, prototypes, algorithms, patents and validation results integrated with research.'),
finance:T('العقود والاشتراكات والإيراد الخارجي والتكاليف والربحية والطاقة ٧٠/٣٠، مع فصل الوفر الداخلي وإلغاء التعاملات الداخلية عند التجميع.','Contracts, subscriptions, external revenue, costs, profitability and 70/30 capacity, separating internal savings and eliminating internal transactions on consolidation.')};return '<p>'+ (descriptions[kind]||descriptions.quality)+'</p>';}
  function qualityMetric(v){if(!Number.isInteger(v.inspected)||!Number.isInteger(v.defective)||v.inspected<=0||v.defective<0||v.defective>v.inspected||!Number.isFinite(v.target)||v.target<0||v.target>100)throw new Error('Invalid quality inputs');const rate=v.defective/v.inspected*100;return {rate,conformance:100-rate,withinTarget:rate<=v.target};}
  HGW.qualityMetric=qualityMetric;
  function communications(){return head('HGW GLOBAL QUANTUM-SECURE SPACE–AIR–GROUND & INTERPLANETARY COMMUNICATIONS',T('الاتصالات والبيانات والشبكات الأرضية والجوية والفضائية','Communications, data & terrestrial–air–space networks'),T('قطاع مستقل لشبكة هجينة آمنة ومترابطة: خدمات على الأرض، وربط جوي وفضائي، ومسار بحثي مستقبلي للاتصالات القمرية وبين الكواكب.','An independent sector for an interconnected secure hybrid network: Earth services, airborne and space links, and a future research track for lunar and interplanetary communications.'))+
    '<section class="hgw-banner"><h2>'+T('طبقات اتصال متعددة، وحماية قابلة للتطوير','Multiple network layers, adaptable protection')+'</h2><p>'+T('تتكامل الألياف والشبكات اللاسلكية والمنصات الجوية والأقمار الصناعية، مع اختيار المسار بحسب التغطية والسعة والتأخير والتكلفة وموثوقية الوصلة. الوصول خارج الأرض هدف مرحلي، وليس تغطية تشغيلية متاحة الآن.','Fiber, wireless, airborne platforms and satellites interoperate, selecting paths by coverage, capacity, latency, cost and reliability. Beyond-Earth access is a phased objective, not an operational coverage claim.')+'</p></section><div class="cards">'+
    card(T('الشبكة الأرضية','Terrestrial network'),T('ألياف ومراكز ربط وحوسبة طرفية وشبكات 5G وخاصة وإنترنت أشياء صناعية، مع دراسة 6G مستقبلًا حسب نضج المعايير. بنية مملوكة انتقائيًا وشركاء مرخّصون.','Fiber, exchange points, edge computing, 5G, private networks and industrial IoT, with future 6G subject to standards maturity; selectively owned infrastructure and licensed partners.'))+
    card(T('الشبكة الجوية','Airborne network'),T('منصات عالية الارتفاع وطائرات وبالونات مناسبة لربط المناطق النائية والاستجابة للأزمات، وفق جدوى الطاقة والتغطية وتراخيص الطيران والطيف.','High-altitude platforms, aircraft and balloons where suitable for remote access and crisis response, subject to power, coverage, aviation and spectrum feasibility.'))+
    card(T('الشبكة الفضائية','Space network'),T('خيارات LEO وMEO وGEO ومحطات أرضية وروابط راديوية وليزرية بين الأقمار وفق متطلبات الخدمة، مع ملاحة وتوقيت وتقييم حمولة خاصة مستقبلًا. لا كوكبة مملوكة مفترضة في البداية.','LEO, MEO and GEO options, ground stations, radio and inter-satellite laser links according to service needs, with navigation/timing and future payload evaluation; no initial owned constellation assumed.'))+
    card(T('خارج الكوكب: القمر وما بعده','Beyond Earth: the Moon and farther'),T('مسار بحثي للأرض والمدار والقمر والمريخ مستقبلًا، مع DTN والتخزين والإرسال المؤجل والملاحة والتوقيت والتشغيل الذاتي عند انقطاع الوصلة. تحده سرعة الضوء ونوافذ الاتصال وميزانية الوصلة.','Research track for Earth, orbit, the Moon and future Mars missions, using DTN, store-and-forward, navigation/timing and autonomous operation during outages; constrained by light speed, contact windows and link budgets.'))+
    card(T('البيانات والخدمات','Data & services'),T('نقل بيانات وصوت وفيديو وتليمترية وحوسبة طرفية وتخزين مرحلي، مع فصل بيانات العملاء وإدارة الإقامة والاحتفاظ والصلاحيات وفق الحقوق والعقود.','Data, voice, video, telemetry, edge computing and intermediate storage, with tenant separation, residency, retention and access governed by rights and contracts.'))+
    card(T('تشفير مقاوم للحوسبة الكمية','Post-quantum cryptography'),T('تشفير المحتوى أثناء النقل والتخزين، مع إدارة مفاتيح ومصادقة وتدرّج لاستخدام ML-KEM لتأسيس المفاتيح وML-DSA أو SLH-DSA للتوقيعات وفق البروتوكولات المتوافقة والاختبار.','Encrypt payloads in transit and at rest with key management, authentication and staged use of ML-KEM for key establishment and ML-DSA or SLH-DSA signatures where protocols and testing support them.'))+
    card(T('توزيع مفاتيح كمي QKD','Quantum key distribution (QKD)'),T('مسار متخصص لوصلات أرضية أو فضائية مناسبة بتجهيزات بصرية وقنوات كلاسيكية موثقة وتقييم الثقة والفقد؛ ليس تشفيرًا شاملًا تلقائيًا ولا قدرة مثبتة بين الكواكب.','Specialist track for suitable terrestrial/space links, requiring optical equipment, authenticated classical channels and trust/loss assessment; not automatic network-wide encryption or demonstrated interplanetary capability.'))+
    card(T('استمرارية الخدمة والجودة','Continuity & quality'),T('مسارات احتياطية ومراقبة وتشخيص وصيانة، ومؤشرات مستقلة للتغطية والتوافر والتأخير والتذبذب وفقد الحزم والسعة وجودة البيانات، بحسب نوع الخدمة.','Redundant paths, monitoring, diagnosis and maintenance, with service-specific coverage, availability, latency, jitter, packet-loss, capacity and data-quality metrics.'))+'</div><div class="cards">'+
    card('70% — '+T('السوق الخارجية','External market'),T('هدف للطاقة الخدمية التجارية للأفراد والمنشآت والحكومات والبحث والخدمات الصناعية والفضائية، وفق الطلب والتراخيص.','Target commercial service capacity for external individuals, businesses, governments, research, industrial and space services, subject to demand and licenses.'))+
    card('30% — '+T('ربط قطاعات HGW','Connecting HGW sectors'),T('هدف لطاقة ربط المصانع والطاقة والمستشفيات والأسواق والمخازن والتوائم الرقمية. تقاس الوفورات الصافية منفصلة عن الإيرادات الخارجية.','Target capacity connecting factories, energy, hospitals, marketplaces, warehouses and digital twins; net internal savings measured separately from external revenue.'))+'</div><section class="panel"><h2>'+T('توأم رقمي للشبكة الهجينة','Hybrid network digital twin')+'</h2><p>'+T('تصميم لمحاكاة المدارات والتغطية والتأخير والفقد والطاقة والأعطال والهجمات وانتقال الاتصال بين الطبقات والكوارث وتكاليف التشغيل، مع سيناريوهات قمرية ومريخية مستقبلية. ترتبط النتائج ببيانات وإصدارات وافتراضات وحدود خطأ ودراسة جدوى قبل الاستثمار؛ لا يوجد توأم شبكة حي في هذه النسخة.','Design for orbit, coverage, delay, loss, energy, fault, attack, inter-layer handover, disaster and operating-cost simulation, including future lunar and Mars scenarios. Results require data provenance, versions, assumptions, uncertainty and pre-investment feasibility; no live network twin is present in this version.')+'</p><a href="./communications-proposal.html">'+T('المقترح الكامل والاسم المؤسسي وخطة التوسع','Full proposal, sector name & expansion plan (Arabic)')+'</a></section><section class="panel"><h2>'+T('مراحل التنفيذ والتكامل','Delivery phases & integration')+'</h2><p>'+T('دراسة طلب وطيف وتراخيص وشركاء ← ربط أرضي وتجارب حماية ← وصلات فضائية تجارية وجوية تجريبية مرخّصة ← تجارب QKD محدودة ← أبحاث اتصالات قمرية وبعيدة وفق بعثات وشراكات فعلية.','Demand, spectrum, licensing and partner study → terrestrial connectivity and security pilots → commercial satellite links and licensed airborne pilots → bounded QKD trials → lunar/deep-space research tied to actual missions and partnerships.')+'</p><p>'+T('الأمن يدير الهوية والمفاتيح والاستجابة؛ البحث يختبر الوصلات والخوارزميات؛ الجودة تتحقق من الأداء والمحاكاة؛ التأمين يقيّم المخاطر؛ ولا تمنح المحاكاة ضمانًا للتغطية.','Cybersecurity manages identity, keys and response; research evaluates links and algorithms; quality validates performance and simulations; insurance assesses risks. Simulation does not guarantee coverage.')+'</p><a href="./communications-plan.html">'+T('الخطة التفصيلية للشبكة الهجينة والاتصالات خارج الأرض','Detailed hybrid and beyond-Earth network plan (Arabic)')+'</a><p class="muted">'+T('هذا تصميم وواجهة تعريفية؛ لا توجد شبكة HGW أرضية أو جوية أو فضائية مفعلة، ولا مفاتيح QKD أو اتصالات خارج الأرض مشغلة في هذه النسخة.','This is a design and informational interface; no HGW terrestrial, airborne or space network, QKD key service or beyond-Earth communications is operational in this version.')+'</p></section>';}
  function cognitive(){return head('HGW GLOBAL KNOWLEDGE INFRASTRUCTURE • UNIVERSAL MIND',T('البنية التحتية المعرفية — مشروع العقل الكوني','Knowledge infrastructure — Universal Mind'),T('بنية معرفية مفتوحة ومستدامة تربط المعرفة الإنسانية والذكاء الاصطناعي والبحث متعدد التخصصات والمحاكاة، لدعم الجامعات والهيئات العامة ومتخذي القرار تحت إشراف بشري.','Open, sustainable knowledge infrastructure connecting human knowledge, AI, interdisciplinary research and simulation to support universities, public bodies and decision-makers under human oversight.'))+
    '<section class="hgw-banner"><h2>'+T('معرفة محفوظة، وأدلة قابلة للتحقق، وقرار بشري','Preserved knowledge, verifiable evidence, human decisions')+'</h2><p>'+T('حفظ العلوم والخبرات وتوثيق مصادرها، وتوسيع الوصول للمعرفة الأساسية، واختبار الفرضيات والسياسات قبل التنفيذ. تدعم النماذج فهم السيناريوهات ولا تتخذ القرار بدل الجهات المختصة أو تضمن النتائج.','Preserve knowledge and expertise with provenance, broaden access to foundational knowledge, and test hypotheses and policies before deployment. Models inform scenarios; they do not replace responsible authorities or guarantee outcomes.')+'</p></section><h2>'+T('أربع طبقات مترابطة','Four connected layers')+'</h2><div class="cards">'+
    card(T('١. الاتصالات ومعالجة البيانات','1. Communications & data processing'),T('معمارية موزعة وحوسبة حافة وربط أرضي وفضائي عبر قطاع الاتصالات، مع قياس التأخير والتوافر واستمرارية الخدمة بدل افتراض اتصال بلا انقطاع.','Distributed architecture, edge computing and terrestrial/space links through the communications sector, with measured latency, availability and continuity rather than assumed uninterrupted connectivity.'))+
    card(T('٢. شبكة البيانات المعرفية','2. Knowledge data network'),T('فهرسة أوراق ونماذج وبيانات بيئية واقتصادية وخبرات، مع مصادر وإصدارات وتراخيص وجودة وصلاحيات واضحة. المصادر العامة مفتوحة حيث تسمح الحقوق؛ الشخصية والسرية مقيدة.','Catalog papers, models, environmental/economic data and expertise with provenance, versions, licenses, quality and access controls. Public resources are open where rights allow; personal and confidential data remain restricted.'))+
    card(T('٣. النماذج والتوائم الرقمية','3. Models & digital twins'),T('نماذج علمية وحضرية واقتصادية وبيولوجية محددة النطاق، ترتبط بمنظومتي البحث والجودة مع معايرة وتحليل حساسية وعدم يقين. لا توجد محاكاة شاملة لكل الأنظمة منفذة هنا.','Scoped scientific, urban, economic and biological models linked to research and quality, with calibration, sensitivity and uncertainty analysis. No universal simulation of all systems is implemented here.'))+
    card(T('٤. الإنسان في مسار الحوكمة','4. Human-in-the-loop governance'),T('مراجعة علمية وأخلاقية، وتفسير الأدلة والافتراضات وتعارض المصالح وسجل قرارات وتظلم. المشاركة العامة والاستشارات والاستفتاءات تخضع للقانون والتفويض والتحقق.','Scientific and ethical review, explainable evidence and assumptions, conflicts of interest, decision logs and appeals. Public consultation and referendums require legal authority and verification.'))+'</div><section class="panel"><h2>'+T('التطبيقات حسب الجهة','Applications by institution')+'</h2><label>'+T('الجهة المستفيدة','Institution')+' <select id="hgw-cognitive-audience"><option value="parliament">'+T('البرلمانات والمجالس التشريعية','Parliaments & legislatures')+'</option><option value="government">'+T('الحكومات والهيئات التنفيذية','Governments & public agencies')+'</option><option value="university">'+T('الجامعات ومراكز البحوث','Universities & research centers')+'</option><option value="industry">'+T('المؤسسات الصناعية والاقتصادية','Industrial & economic institutions')+'</option></select></label><div id="hgw-cognitive-use" aria-live="polite">'+cognitiveUse('parliament')+'</div><p class="muted">'+T('استعراض لحالات استخدام مقترحة، وليس اتصالًا بجهة أو نظام حكومي أو بيانات حية.','Proposed use cases, not a connection to public institutions, government systems or live data.')+'</p></section><div class="cards">'+
    card(T('المرحلة الأولى: السنوات ١–٢','Phase 1: years 1–2'),T('بروتوكولات ونواة معرفة تجريبية مع مراكز مختارة، بعد الاتفاق على الحقوق والحوكمة والتحقق.','Protocols and a pilot knowledge core with selected centers, subject to rights, governance and validation agreements.'))+
    card(T('المرحلة الثانية: السنوات ٣–٤','Phase 2: years 3–4'),T('تجارب تقييم أثر تشريعي وتنموي مع جهات مفوضة وشركاء فعليين.','Legislative/development impact pilots with authorized institutions and actual partners.'))+
    card(T('المرحلة الثالثة: السنوات ٥–٦','Phase 3: years 5–6'),T('توسع مؤسسي ودولي مشروط بالنتائج والتمويل واعتماد الشركاء. الفترات إطار زمني مقترح وليست مواعيد إطلاق معتمدة.','Institutional and international scale conditional on outcomes, funding and partner approval. Ranges are proposed planning windows, not approved launch dates.'))+'</div><section class="panel"><h2>'+T('ثلاثة مستويات لخدمة المعرفة','Three knowledge service levels')+'</h2><ol><li>'+T('المعرفة المفتوحة: نواة عامة مجانية وفق الحقوق والتراخيص.','Open knowledge: free public core subject to rights and licenses.')+'</li><li>'+T('الذكاء المؤسسي: تحليل ومحاكاة وتوائم للجامعات والحكومات والشركات.','Institutional intelligence: analysis, simulation and twins for universities, governments and businesses.')+'</li><li>'+T('الذكاء التشغيلي الداخلي: بيانات ونماذج مشتركة بصلاحيات مستقلة لقطاعات HGW.','Internal operational intelligence: shared data and models with independent sector permissions.')+'</li></ol><h3>'+T('الهيكل المؤسسي المقترح','Proposed institutional structure')+'</h3><p>HGW Non-Profit Foundation → HGW Universal Mind Institute → HGW Knowledge Infrastructure Operations / HGW Digital Simulation Services</p><p>'+T('إشراف غير ربحي على الرسالة، ومعهد علمي للمعايير والحوكمة، ووحدة تشغيل تقني ووحدة خدمات تجارية. لا يثبت هذا المخطط تأسيس الجهات أو علاقات ملكيتها قانونيًا.','Nonprofit mission oversight, a scientific institute for standards/governance, technical operations and commercial services. This diagram does not establish incorporation or legal ownership relationships.')+'</p></section><section class="panel"><h2>'+T('توزيع رأس المال المستهدف — مقترح','Proposed target capital allocation')+'</h2><div class="tablewrap"><table class="table"><thead><tr><th>'+T('البند','Item')+'</th><th>USD</th></tr></thead><tbody>'+'<tr><td>'+T("الذكاء الاصطناعي والنماذج","AI & models")+'</td><td>'+money(5000000)+'</td></tr>'+'<tr><td>'+T("المحاكاة والتوأمة الرقمية","Simulation & twins")+'</td><td>'+money(4000000)+'</td></tr>'+'<tr><td>'+T("البنية التحتية والحوسبة","Infrastructure & computing")+'</td><td>'+money(4000000)+'</td></tr>'+'<tr><td>'+T("شبكات البيانات والمعرفة","Knowledge & data networks")+'</td><td>'+money(2500000)+'</td></tr>'+'<tr><td>'+T("الأمن السيبراني والحوكمة","Security & governance")+'</td><td>'+money(1500000)+'</td></tr>'+'<tr><td>'+T("البحث والشراكات","Research & partnerships")+'</td><td>'+money(2000000)+'</td></tr>'+'<tr><td>'+T("الإدارة والتراخيص والتشغيل","Administration, licensing & operations")+'</td><td>'+money(1500000)+'</td></tr>'+'<tr><td>'+T("احتياطي المخاطر والطوارئ","Risk & contingency reserve")+'</td><td>'+money(1500000)+'</td></tr>'+ '<tr><th>'+T('الإجمالي','Total')+'</th><th>'+money(22000000)+'</th></tr></tbody></table></div><p>'+T('٢٢ مليونًا من سيناريو ٣٠٠ مليون = ٧٫٣٣٪ تقريبًا؛ الفرق الحسابي ٢٧٨ مليونًا قبل بقية تخصيصات القطاعات، وليس رصيدًا نقديًا متاحًا. مراجعة الازدواجية تشمل الحوسبة والاتصالات والأمن والبحث والتوائم، وتُوثَّق أي استقطاعات قبل اعتماد الخطة المجمعة.','The $22m request is approximately 7.33% of the $300m scenario; the $278m arithmetic difference is before all other sector allocations, not available cash. Reconcile shared computing, communications, security, research and twins, recording deductions before consolidated approval.')+'</p><a href="./universal-mind-proposal.html">'+T('الصياغة المؤسسية الكاملة المحدثة','Updated full institutional proposal (Arabic)')+'</a></section><section class="panel"><h2>'+T('التمويل ونموذج الإتاحة','Funding & access model')+'</h2><p>'+T('يقترح المرفق ٢٢ مليون دولار للتأسيس والبرمجيات والنماذج والأمن والحوسبة والتشغيل والشراكات، بتوزيع تخطيطي موضح أدناه غير معتمد هندسيًا. أُدرج كطلب تخصيص ضمن سيناريو سقف ٣٠٠ مليون دولار، ولا يُعد تمويلًا متاحًا أو مصروفًا.','The proposal suggests $22m for setup, software, models, security, computing, operations and partnerships, with the provisional allocation shown below, not an engineering-approved estimate. Recorded as an allocation request within the $300m envelope scenario, not as available or spent funds.')+'</p><p>'+T('نواة معرفية مفتوحة أو مجانية وفق حقوق الإتاحة، وخدمات محاكاة واستشارات وتوائم مدفوعة، مع منح وشراكات تُفصل محاسبيًا عن المبيعات. نموذج ٧٠/٣٠ ينطبق على الطاقة الخدمية التجارية المستهدفة، ولا يقيد إتاحة النواة المفتوحة.','An open or free knowledge core subject to access rights, with paid simulation, consulting and twin services. Grants and partnerships are accounted for separately from sales. The 70/30 target applies to commercial service capacity, not access to the open core.')+'</p><p>'+T('توقعات المرفق التراكمية: ٥٠ مليون دولار خلال ٥ سنوات، و٣٥٠ مليونًا خلال ١٠ سنوات، و١٫٨ مليار خلال ٢٠ سنة. افتراضات صاحب المقترح تحتاج نموذج طلب وتسعير وتكاليف وتدفقات وسيناريوهات؛ ليست إيرادات محققة أو أرباحًا أو تقييمًا مثبتًا.','Proposal cumulative revenue assumptions: $50m over 5 years, $350m over 10, and $1.8bn over 20. These require demand, pricing, cost, cash-flow and scenario models; they are not realized revenue, profit or validated valuation.')+'</p><a href="./cognitive-proposal.html">'+T('اقرأ مشروع العقل الكوني كاملًا','Read the full Cosmic Mind proposal (Arabic)')+'</a><br><a href="./cognitive-plan.html">'+T('خطة التكامل والحوكمة','Integration & governance plan (Arabic)')+'</a><p class="muted">'+T('المنفذ واجهة وخطة؛ لم تُنشر بنية معرفية مركزية أو ذكاء اصطناعي تشغيلي أو تكامل حكومي أو محاكاة حية.','Implemented as an interface and plan; no central knowledge backend, operational AI, government integration or live simulation is deployed.')+'</p></section>';}
  function cognitiveUse(kind){const uses={industry:T('توائم المصانع وتحسين الإنتاج والطاقة والصيانة وسلاسل الإمداد وتقييم مخاطر الاستثمار وتصميم المنتجات واختبارها افتراضيًا.','Factory twins, production and energy optimization, maintenance, supply chains, investment-risk assessment and virtual product design/testing.'),parliament:T('مقارنة بدائل القوانين والسياسات وآثارها الاجتماعية والاقتصادية قصيرة وطويلة الأجل، مع كشف الافتراضات والآراء المخالفة ومراجعة خبراء وتوثيق القرار. المشاركة شفافة ومصرح بها.','Compare legislative and policy alternatives and short/long-term social and economic effects, disclosing assumptions and dissenting evidence, with expert review and decision records. Participation is transparent and authorized.'),government:T('تخطيط الطاقة والموارد والبنية التحتية والاستدامة، وسيناريوهات الأزمات والطوارئ عبر بيانات مصرح بها. أي تحكم تشغيلي أو استجابة آلية يتطلب تفويضًا وتحقق سلامة مستقلًا؛ الوضع المبدئي استشاري.','Plan energy, resources, infrastructure and sustainability, with crisis scenarios using authorized data. Operational control or automated response requires authorization and independent safety validation; initial use is advisory.'),university:T('مختبر افتراضي وتعاون متعدد التخصصات للوصول إلى بيانات مرخصة وحوسبة ونماذج عند توفير الموارد، واختبار فرضيات وتكرار النتائج وتوثيق المساهمات والحقوق.','A virtual lab and interdisciplinary collaboration accessing licensed data, computing and models where resources exist, with hypothesis testing, reproducibility, contribution records and rights.')};return '<p>'+(uses[kind]||uses.university)+'</p>';}
  function devices(){return head('ONE PLATFORM • MANY DEVICES',T('HGW على أجهزتك','HGW on your devices'),T('واجهة ويب متجاوبة للموبايل والكمبيوتر والتابلت، قابلة للتثبيت كتطبيق ويب على المتصفحات الداعمة.','Responsive web experience for phones, computers and tablets; installable as a web app in supporting browsers.'))+
    '<section class="panel"><h2>'+T('تثبيت نسخة الويب','Install the web app')+'</h2><button class="btn" type="button" id="hgw-install">'+T('عرض خيارات التثبيت','Show install options')+'</button><p id="hgw-install-status" role="status"></p><p>'+T('Android وSamsung: من قائمة Chrome أو Samsung Internet اختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية». iPhone وiPad: من Safari ← مشاركة ← إضافة إلى الشاشة الرئيسية ← فتح كتطبيق إن ظهر الخيار.','Android & Samsung: use Install app or Add to Home screen in Chrome or Samsung Internet. iPhone & iPad: Safari → Share → Add to Home Screen → Open as Web App when offered.')+'</p><p>'+T('Windows وmacOS وLinux: افتح الموقع في متصفح حديث؛ التثبيت يعتمد على المتصفح وإصداره. بقية الأنظمة تستطيع استخدام نسخة الويب إذا كانت تدعم تقنيات الويب المطلوبة.','Windows, macOS & Linux: open in a modern browser; installation depends on browser and version. Other systems can use the website if required web features are supported.')+'</p><p>'+T('يتطلب التثبيت اتصال HTTPS أو localhost. التصفح دون اتصال يصبح متاحًا بعد أول تحميل ناجح؛ البيانات التجريبية محلية ولا تتزامن بين الأجهزة.','Installation requires HTTPS or localhost. Offline browsing becomes available after a successful first load; demo data stays local and does not sync across devices.')+'</p></section><div class="cards">'+card('Google Play / Samsung Galaxy Store',T('مسار حزمة Android لاحقًا؛ لم تُبنَ أو تُوقّع أو تُنشر حزمة متجر في هذه النسخة.','Android packaging path pending; no store binary built, signed or published in this version.'))+card('Apple App Store / Mac App Store',T('تحتاج حزم Apple وبناء على macOS وتوقيع وحساب مطوّر واختبار ومراجعة المتجر.','Requires Apple packages, macOS builds, signing, a developer account, testing and store review.'))+card('Windows / Linux / '+T('متاجر أخرى','Other stores'),T('تغليف سطح المكتب وتوزيعات Linux وبقية المتاجر مراحل مستقلة؛ لا يُفترض توافق كل نظام دون اختبار.','Desktop packaging, Linux distributions and other stores require separate release work; compatibility must be tested.'))+'</div>';}
  HGW.render=function(page,l){lang=l;return ({insurance,circular,logistics,cyber,research,quality,communications,cognitive,devices}[page]||insurance)();};
  function values(form){return Object.fromEntries([...form.querySelectorAll('input')].map(i=>[i.id,Number(i.value)]));}
  document.addEventListener('change',e=>{if(e.target.id==='hgw-cognitive-audience')document.getElementById('hgw-cognitive-use').innerHTML=cognitiveUse(e.target.value);if(e.target.id==='hgw-quality-dashboard')document.getElementById('hgw-quality-dashboard-content').innerHTML=qualityDashboard(e.target.value);if(e.target.id==='hgw-knowledge-type')document.getElementById('hgw-knowledge-record').innerHTML=knowledgeRecord(e.target.value);if(e.target.id==='hgw-audience')document.getElementById('hgw-protection').innerHTML=protection(e.target.value);});
  document.addEventListener('submit',e=>{
    if(!['hgw-landed','hgw-finance','hgw-quality'].includes(e.target.id))return;
    e.preventDefault(); const isCost=e.target.id==='hgw-landed', out=document.getElementById(e.target.id+'-result');
    try{const v=values(e.target);if(e.target.id==='hgw-quality'){const q=qualityMetric(v);out.textContent=T('معدل العيوب: ','Defect rate: ')+q.rate.toFixed(2)+'% · '+T('مطابقة الوحدات: ','Conforming units: ')+q.conformance.toFixed(2)+'% · '+(q.withinTarget?T('ضمن الهدف العددي؛ يلزم تقييم بقية المتطلبات.','Within numeric target; other requirements need assessment.'):T('تجاوز الهدف؛ يلزم تحليل السبب وإجراء تصحيحي.','Target exceeded; root-cause analysis and corrective action required.'));return;}if(isCost){const n=landed(v);out.innerHTML='<h3>'+T('التكلفة الإجمالية التقديرية: ','Estimated total: ')+money(n.total)+'</h3><p>'+T('الجمارك: ','Duty: ')+money(n.duty)+' · '+T('الضريبة: ','Tax: ')+money(n.vat)+'</p><p>'+(n.saving===null?T('أدخل سعرًا مرجعيًا موجبًا لحساب الوفر.','Enter a positive reference price to calculate savings.'):T('الفرق مقابل البديل: ','Savings vs reference: ')+n.saving.toFixed(1)+'%')+'</p><small>'+T('الهدف ٥٠–٨٠٪؛ النتيجة أعلاه محسوبة ولا تُفرض للوصول للهدف. يجب تكافؤ البديل في الحالة والجودة والخدمات.','Target 50–80%; result is calculated, not forced to meet the target. Compare equivalent condition, quality and services.')+'</small>';}else{const n=finance(v);out.innerHTML='<h3>'+T('نتيجة السيناريو السنوي','Annual scenario')+'</h3><p>'+T('حجم التداول: ','GMV: ')+money(n.gmv)+'</p><p>'+T('إيراد HGW الخارجي: ','External HGW revenue: ')+money(n.revenue)+'</p><p>'+T('المساهمة التشغيلية بعد المصروفات الثابتة: ','Operating contribution after fixed costs: ')+money(n.operating)+'</p><p>'+T('معاملات التعادل: ','Break-even transactions: ')+(n.breakeven??T('غير متاحة دون مساهمة موجبة','Unavailable without positive contribution'))+'</p><p>'+T('المتبقي من سقف المشروع لبقية الاستخدامات: ','Project envelope remaining for other uses: ')+money(n.remaining)+'</p>';}}catch(err){out.textContent=T('راجع المدخلات والحدود المسموح بها.','Check inputs and permitted limits.');}
  });
  root.HGW=HGW;
})(typeof window!=='undefined'?window:globalThis);
